<!doctype html><html><head><meta charset="utf-8"><title>Flight Routes</title><style>body{font-family:Arial,sans-serif;background:#f4f7fb;color:#14223a;margin:0;padding:28px}.fr-wrap{max-width:1100px;margin:auto}.fr-head{display:flex;justify-content:space-between;align-items:flex-start;margin-bottom:20px}.fr-head h1{margin:4px 0;font-size:28px}.fr-head p{color:#64748b}.fr-btn,.fr-tab{display:inline-block;padding:9px 13px;border:1px solid #cbd5e1;border-radius:7px;background:#fff;color:#17396c;text-decoration:none}.fr-tab.active{background:#e8f0ff;border-color:#2563eb}.fr-nav{display:flex;gap:8px;margin-bottom:16px}.fr-card{background:#fff;border:1px solid #e2e8f0;border-radius:10px;padding:18px;box-shadow:0 2px 8px #0f172a0d}.fr-table{width:100%;border-collapse:collapse}.fr-table th,.fr-table td{padding:11px 10px;border-bottom:1px solid #e2e8f0;text-align:left}.fr-table th{font-size:11px;text-transform:uppercase;color:#64748b}.fr-empty{padding:36px;text-align:center;color:#64748b}</style></head><body><main class="fr-wrap"><div class="fr-head"><div><div style="font-size:11px;text-transform:uppercase;color:#2563eb;font-weight:700">Airlines</div><h1>Flight Routes</h1><p>Derived from saved Tickets / Flight Data itinerary history. Read-only; no separate Route Master is created.</p></div><a class="fr-btn" href="{{ url('/master-data/travel-masters?tab=airlines') }}">← Travel Masters</a></div><nav class="fr-nav"><a class="fr-tab" href="{{ url('/master-data/travel-masters?tab=airlines') }}">Airlines</a><a class="fr-tab active" href="{{ route('travel-masters.flight-routes') }}">Flight Routes</a></nav><section class="fr-card">@if(!$available || !$routes)<div class="fr-empty">No flight routes recorded yet.</div>@else<table class="fr-table"><thead><tr><th>Route</th><th>From</th><th>To</th><th>Airlines Used</th><th>Flight Nos</th><th>Used</th></tr></thead><tbody>@foreach($routes as $route)<tr><td>{{ $route['route'] }}</td><td>{{ $route['from'] }}</td><td>{{ $route['to'] }}</td><td